import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { useState } from 'react';

export default function Header() {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { href: '/#about', label: 'About' },
    { href: '/#contact', label: 'Contact' },
  ];

  return (
    <header className="sticky top-0 z-50 bg-background/90 backdrop-blur-md border-b border-border/40">
      <div className="max-w-6xl mx-auto px-6 md:px-10">
        <div className="flex h-20 items-center justify-between">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0" aria-label="Alex Morgan — Home">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="AM logo"
              className="h-9 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-8">
            {navItems.map((item) => (
              <a
                key={item.href}
                href={item.href}
                className="relative text-sm font-medium tracking-wide text-foreground/70 hover:text-foreground transition-colors duration-200 group"
              >
                {item.label}
                <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-primary transition-all duration-300 group-hover:w-full" />
              </a>
            ))}
            <a
              href="mailto:hello@alexmorgan.com"
              className="text-sm font-medium tracking-wide px-4 py-2 border border-foreground/20 rounded-sm text-foreground/80 hover:border-primary hover:text-primary transition-all duration-200"
            >
              Say Hello
            </a>
          </nav>

          {/* Mobile Toggle */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 text-foreground/70 hover:text-foreground transition-colors"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border/40 py-5">
            <nav className="flex flex-col gap-4">
              {navItems.map((item) => (
                <a
                  key={item.href}
                  href={item.href}
                  className="text-sm font-medium text-foreground/70 hover:text-foreground transition-colors py-1"
                  onClick={() => setIsMobileMenuOpen(false)}
                >
                  {item.label}
                </a>
              ))}
              <a
                href="mailto:hello@alexmorgan.com"
                className="text-sm font-medium text-primary"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                Say Hello
              </a>
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

export default function Footer() {
  const currentYear = new Date().getFullYear();

  return (
    <footer className="border-t border-border/40 bg-background">
      <div className="max-w-6xl mx-auto px-6 md:px-10 py-10">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          {/* Left: Monogram + tagline */}
          <div className="flex flex-col gap-1">
            <span className="font-heading text-lg font-normal text-foreground tracking-tight">
              Alex Morgan
            </span>
            <span className="text-xs text-muted-foreground tracking-widest uppercase">
              Designer &amp; Developer
            </span>
          </div>

          {/* Center: Thin decorative line */}
          <div className="hidden md:block flex-1 mx-10 h-px bg-border/60" />

          {/* Right: Copyright */}
          <div className="text-xs text-muted-foreground">
            © {currentYear} Alex Morgan. All rights reserved.
          </div>
        </div>
      </div>
    </footer>
  );
}

